  "표5_매튜헨리": [
    {"영어원문": "The red horse, and his bloody rider, speaketh of war and mutual slaughter — the sword that God hangeth over nations when they will not know the things of their peace.", "한국어번역": "매튜 헨리는 붉은 말과 피 묻은 말 탄 자가 전쟁과 상호 살육을 의미한다고 설명한다. 나라들이 화평의 일을 알지 못할 때 하나님이 매달아 두시는 칼이다", "핵심통찰": "전쟁의 칼"},
    {"영어원문": "Power was given unto him; no tyrant draws his sword but by the sufferance of the Lord of hosts.", "한국어번역": "매튜 헨리는 그에게 권세가 주어졌음을 지적한다. 어떤 폭군도 만군의 주의 허락 없이는 칼을 뽑지 못한다", "핵심통찰": "주어진 권세"},
    {"영어원문": "That men should kill one another — the saddest of all wars, when the hand of brother is lifted up against brother.", "한국어번역": "매튜 헨리는 사람들이 서로 죽이는 것이 가장 슬픈 전쟁이라고 한다. 형제의 손이 형제를 치는 때이다", "핵심통찰": "형제의 상호 살육"},
    {"영어원문": "A great sword was given unto him — the sword of state, the sword of war, both turned from their right use unto slaughter.", "한국어번역": "매튜 헨리는 그에게 큰 칼이 주어졌다고 설명한다. 국가의 칼과 전쟁의 칼이 모두 본래 용도에서 떠나 살육으로 변한 것이다", "핵심통찰": "본래 용도에서 떠난 칼"},
    {"영어원문": "When the Prince of Peace is rejected, peace itself is taken from the earth.", "한국어번역": "매튜 헨리는 평강의 왕이 거절되면 평강 자체가 땅에서 제거된다고 가르친다", "핵심통찰": "거절된 평강의 왕"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "붉은 말 - 거부된 평강의 왕", "예화_적용": "적용: 평강의 왕 그리스도를 영접하는 것이 참된 평화의 길이다"},
    {"대지": "서론", "내용": "정복 다음엔 피의 역사가 온다. 붉은 말이 나타난다", "예화_적용": "1차 세계대전 후 2차 세계대전이 왔듯 전쟁은 전쟁을 낳는다"},
    {"대지": "1대지: 화평이 제거됨 (은혜의 철회)", "내용": "땅의 화평은 하나님의 은혜의 선물이며 철회될 수 있다", "예화_적용": "공짜로 누리던 햇빛도 구름이 가리면 사라진다. 평화도 그러하다"},
    {"대지": "2대지: 서로 죽임 (관계의 파괴)", "내용": "죄는 수직적(하나님과)으로만 아니라 수평적(사람과) 관계도 파괴한다", "예화_적용": "도미노가 한 번 넘어지면 전체가 무너지듯 관계의 파괴는 연쇄적이다"},
    {"대지": "3대지: 큰 칼이 주어짐 (허용된 권세)", "내용": "악의 권세조차 하나님의 허용 안에 있다", "예화_적용": "목줄에 묶인 개가 가는 만큼만 움직이듯 악도 하나님이 허용하신 만큼만 한다"},
    {"대지": "결론", "내용": "평강의 왕 그리스도께로 돌이키자. 그분만이 참 화평이시다", "예화_적용": "화재경보가 울리면 소방대로 달려가듯 전쟁의 시대에 그리스도께로 달려가자"}
  ],
